&lt;li&gt;&lt;span data-ccp-props="{&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[281],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}"&gt;Fluent level of &lt;strong&gt;English and French&lt;/strong&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;Previous&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;&amp;nbsp;sales experience&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;, ideally&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;&amp;nbsp;of high-tech products/services&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;,&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;&amp;nbsp;is&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;&amp;nbsp;a plus&lt;/span&gt;&lt;span data-ccp-parastyle="Numbers 1"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240,&amp;quot;469777462&amp;quot;:[281],&amp;quot;469777927&amp;quot;:[0],&amp;quot;469777928&amp;quot;:[1]}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
